export const numberFormat = new Intl.NumberFormat('ru-RU');
export const dateFormat = new Intl.DateTimeFormat('ru-RU', {
  timeZone: 'Europe/Moscow', day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit'
});

export const byId = <T extends HTMLElement = HTMLElement>(id: string) => document.getElementById(id) as T;

export type FetchJson<T> = T & { error?: string };

export type ViewStatePayload = {
  view_profile?: { block_order?: unknown[]; highlights?: unknown[]; default_filters?: Record<string, string> };
  active_situations?: Array<{ title?: string; description?: string; priority?: number }>;
};

export type ViewStateResponse = { view_profile?: { block_order?: string[]; highlights?: string[]; default_filters?: Record<string, string> } } & ViewStatePayload;

export function updateSituationsPanel(payload: ViewStatePayload) {
  const panel = byId('situations-panel');
  const list = byId('situations-list');
  if (!panel || !list) return;
  list.replaceChildren();
  const situations = payload?.active_situations || [];
  if (!Array.isArray(situations) || situations.length === 0) {
    panel.hidden = true;
    return;
  }
  situations.forEach((item) => {
    const card = document.createElement('div');
    card.className = 'situation-item';
    const title = document.createElement('div');
    title.className = 'situation-name';
    title.textContent = item.title || 'Ситуация';
    const desc = document.createElement('div');
    desc.className = 'situation-desc';
    desc.textContent = item.description || '';
    const priority = document.createElement('div');
    priority.className = 'situation-priority';
    priority.textContent = `Приоритет: ${numberFormat.format(Number(item.priority || 0))}`;
    card.append(title, desc, priority);
    list.append(card);
  });
  panel.hidden = false;
}

export function applyViewProfile(payload: ViewStateResponse) {
  const container = byId('page-blocks');
  if (!container) return;
  const profile = payload?.view_profile || {};
  const order: string[] = Array.isArray(profile.block_order)
    ? profile.block_order.map((item: unknown) => String(item))
    : [];
  const highlights = new Set<string>(Array.isArray(profile.highlights) ? profile.highlights.map((item: unknown) => String(item)) : []);
  const blocks = Array.from(container.querySelectorAll<HTMLElement>('[data-block]'));
  const orderIndex = new Map<string, number>(order.map((key, index) => [key, index] as const));
  blocks.forEach((block) => {
    const name = block.dataset.block || '';
    const index = orderIndex.has(name) ? orderIndex.get(name)! : Number.MAX_SAFE_INTEGER;
    block.style.order = String(index);
    block.classList.toggle('is-promoted', index < 2 && order.length > 0);
    block.classList.toggle('is-highlighted', highlights.has(name));
    block.hidden = order.length > 0 && !orderIndex.has(name);
  });
}

export function formatDate(raw?: string) {
  if (!raw) return 'Нет данных';
  const date = new Date(raw);
  return Number.isNaN(date.getTime()) ? 'Нет данных' : dateFormat.format(date);
}

export function formatDuration(minutes?: number) {
  if (minutes == null || !Number.isFinite(Number(minutes))) return 'Нет данных';
  const value = Math.max(0, Math.round(Number(minutes)));
  if (value < 60) return `${numberFormat.format(value)} мин`;
  const hours = Math.floor(value / 60);
  if (hours < 48) return `${numberFormat.format(hours)} ч ${value % 60} мин`;
  const days = Math.floor(hours / 24);
  return `${numberFormat.format(days)} дн ${hours % 24} ч`;
}

export function formatDays(days?: number) {
  if (days == null || !Number.isFinite(Number(days))) return 'Нет данных';
  const value = Number(days);
  if (value < 1) return formatDuration(value * 1440);
  return `${new Intl.NumberFormat('ru-RU', { maximumFractionDigits: 1 }).format(value)} дн`;
}

export function tail(uri?: string) {
  return uri ? uri.substring(uri.lastIndexOf('/') + 1) : '';
}
